    bool? BofaPresent();
    void SetDoorMagnet(bool on);
    void SetDamper(bool open);
    bool? DamperOpen { get; }
    string? DamperDriver { get; }        // "pio" / "lgpio", null until first driven
    void SetLight(bool on);
    void NfcReset();
