*Public contract:*
```csharp
public interface IUsbMounts { IReadOnlyList<string> Mounts(); string? Find(); }
public sealed class UsbMounts : IUsbMounts { }
public interface ISystemService {
  OpResult Reboot(); OpResult Shutdown();
