public sealed partial class SystemService : ISystemService {
  public const string NoUsbMessage = "No Disk-on-Key found. Please connect a Disk-on-Key (USB drive).";
  public static readonly string[] RebootCommand = { "sudo", "reboot" };
  public SystemService(IUsbMounts usb, TimeProvider? time = null, ILogger<SystemService>? logger = null, string? baseDir = null, ISupervisorClient? supervisor = null);
  public static string SanitizeFileName(string? filename, string fallback);
}
public sealed record VersionInfoDto {   // JSON: appVersion, gitCommit, gitDate, lastBoot, os, kernel, python, runtime, emmcSerial
  string AppVersion = "unknown"; string? GitCommit, GitDate, LastBoot, Os, Kernel, Python, Runtime, EmmcSerial; }
public sealed record ExportResultDto { bool Ok "ok"; string Message "message" = ""; string? Path "path" (omit null); int? Code "code" (omit null); }
```
*Behaviour & rules:*
# {{UsbMounts.Mounts()}} on Linux: (a) lines of {{/proc/mounts}} starting {{/dev/sd}}, mount point ({{\040}} → space) under {{/media/}}, {{/run/media/}} or one of fixed {{/media/usb}}, {{/media/pi}}, {{/mnt/usb}}; (b) two-level scan of {{/media/*/*}} and {{/run/media/*/*}} keeping mount points; (c) {{/mnt/usb*}} mount points; (d) fixed points that are mount points; keep existing dirs, distinct, *writable first* (writability probe: create+delete {{.scure-write-<pid>}}). Mount point test = {{mountpoint -q <path>}} exit 0 (3 s timeout). Off-Linux: {{DriveInfo}} removable + ready drives.
# {{Find()}}: first of {{Mounts()}}; else (Linux only) last resort: for {{/dev/sda1}}, {{/dev/sdb1}} that exist, create {{/media/usb}}, run {{mount <dev> /media/usb}} (10 s), return it if now a mount point; else null.
# {{Reboot}}: log {{"[SYSTEM] Rebooting: sudo reboot"}}; off-Linux → Success "Reboot simulated"; else {{Fire("sudo","reboot")}} → "Rebooting..." or Fail "sudo reboot could not be started". {{Shutdown}}: {{systemctl poweroff}} → "Shutting down..." / "Shutdown simulated".
# {{Version()}}: {{AppVersion}} = first line of {{<baseDir>/VERSION}} (trimmed, non-empty) else entry assembly {{AssemblyInformationalVersion}} up to '+', else {{Version.ToString(3)}}, else "unknown". {{GITINFO}} file in baseDir: line 1 = commit, line 2 = date (null if blank). {{LastBoot}} = {{uptime -s}} on Linux, else now − {{Environment.TickCount64}} formatted {{yyyy-MM-dd HH:mm:ss}}. {{Os}} = {{PRETTY_NAME}} from {{/etc/os-release}} (quotes stripped) else {{RuntimeInformation.OSDescription}}. {{Kernel}} = {{uname -r}} (Linux) or {{Environment.OSVersion.Version}}. {{Python}} = null always. {{Runtime}} = {{RuntimeInformation.FrameworkDescription}}. {{EmmcSerial}} = {{EmmcIdentity.ReadSerial()}}.
# {{ExportLogs}}: no USB → Fail("No USB drive found", 9083). Stamp {{yyyyMMdd-HHmmss}} (local). If {{/var/log/scure}} exists → recursive copy to {{<usb>/scure-logs-<stamp>/}}; else write {{<usb>/scure-logs-<stamp>.txt}} with {{journalctl -u scurebox --no-pager}} stdout (30 s, Linux) or {{"No logs available on this host (<OSDescription>)\n"}}. Then {{sync}} (Linux, 30 s). Success "Logs exported to USB". IO/access errors → Fail(msg, 9083).
# {{ExportCsv}} / {{ExportReport}}: name = {{SanitizeFileName(filename, "untitled.csv" | "cure-report.html")}}; append {{.csv}}/{{.html}} if missing (case-insensitive). No USB → {{{Ok=false, Code=9081, Message=NoUsbMessage}}}. Write UTF-8 no BOM to {{<usb>/<name>}}, {{sync}}; → {{{Ok=true, Message="Saved <name> to USB", Path=dest}}}. IO/access/NotSupported → {{{Ok=false, Code=9082, Message=e.Message}}}.
# {{SanitizeFileName}}: replace {{\}} by {{/}}, take text after last {{/}}, trim, replace every {{Path.GetInvalidFileNameChars()}} with {{_}}; empty, {{.}} or {{..}} → fallback.
*Configuration:* {{<baseDir>/VERSION}}, {{<baseDir>/GITINFO}} (baseDir default {{AppContext.BaseDirectory}}).
*Acceptance criteria:*
* Export with {{FakeUsbMounts}} returning null → code 9081 and the exact NoUsbMessage.
* {{ExportCsv("../../etc/passwd", "x")}} writes {{passwd.csv}} inside the USB dir.
* A read-only/invalid target → code 9082.
* {{Version()}} reads VERSION + GITINFO from baseDir; without VERSION falls back to the assembly version.
* Off Windows/Linux-less tests: Reboot/Shutdown report "simulated"; on Linux {{RebootCommand}} is exactly {{sudo reboot}}.
*Tests:* {{Platform/SystemServiceTests}} (Export_without_a_usb_drive_is_9081, Export_writes_sanitised_file_names_with_the_forced_extension, Export_write_error_is_9082, File_names_are_reduced_to_a_safe_basename, Version_reads_the_version_and_gitinfo_files_next_to_the_executable, Version_falls_back_to_the_assembly_version_without_a_version_file, Date_time_format_is_validated, Power_actions_are_simulated_off_device, Reboot_runs_sudo_reboot); helper {{Platform/FakeUsbMounts}}.
